-- 先按运维说明盘点重复身份, 发现冲突时停止升级, 不自动合并或删除账号.
ALTER TABLE WX_USER
  MODIFY MA_OPENID VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  MODIFY OPENID VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  MODIFY UNION_ID VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  ADD UNIQUE KEY uk_cc_ma_openid(MA_OPENID),
  ADD UNIQUE KEY uk_cc_openid(OPENID);

CREATE TABLE CC_LOGIN_IDENTITY_LOCK (
  identity_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  user_id BIGINT NULL COMMENT '经服务端验证后绑定的账户, 不保存原始身份',
  touched_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
